-- MCQ FORM — cụm "Bài toán thực tế" (25 dạng, khối 9): 4 rule DÙNG CHUNG cho MỌI dạng, vì cách sinh nhiễu
-- không đọc-hiểu đề (CEO chốt 14/09: đáp số kho đã duyệt sẵn, máy chỉ cần áp lỗi tính toán phổ biến lên đáp
-- số ĐÃ CÓ, không cần hiểu tình huống bài toán — xem hàm mới `sinhNhieuDapSoThucTe`, mini-dang.mjs DẠNG 52).
insert into dai_mcq_rule (ma, ten, mo_ta, vi_du, nhom, ap_dung, du_phong) values
('R343','Bài toán thực tế: hoán đổi 2 giá trị / tính gấp đôi','Hoán đổi nhầm 2 đại lượng cần tìm (nếu đáp số có 2 giá trị), hoặc tính gấp đôi giá trị đúng — quên chia đôi ở 1 bước (nếu đáp số chỉ 1 giá trị)','Đúng "90; 60" → nhầm "60; 90"','khai_niem','{T109010301,T109010302,T109010304,T109010305,T109010306,T109010307,T109010308,T109010309,T109020301,T109020302,T109020303,T109020304,T109020305,T109020306,T109020307,T109090101,T109090102,T109090201,T109090202,T109090301,T109090302,T109090303,T109090304,T109090305,T109090401}',false),
('R344','Bài toán thực tế: lệch 1 đơn vị ở giá trị thứ nhất','Tính đúng cấu trúc nhưng giá trị đầu tiên lệch 1 đơn vị','Đúng "90; 60" → nhầm "91; 60"','tinh','{T109010301,T109010302,T109010304,T109010305,T109010306,T109010307,T109010308,T109010309,T109020301,T109020302,T109020303,T109020304,T109020305,T109020306,T109020307,T109090101,T109090102,T109090201,T109090202,T109090301,T109090302,T109090303,T109090304,T109090305,T109090401}',false),
('R345','Bài toán thực tế: lệch 1 đơn vị ở giá trị thứ nhất, chiều ngược lại','Rule dự phòng — đúng cấu trúc nhưng giá trị đầu tiên lệch 1 đơn vị theo chiều ngược lại với R344','Đúng "90; 60" → nhầm "89; 60"','tinh','{T109010301,T109010302,T109010304,T109010305,T109010306,T109010307,T109010308,T109010309,T109020301,T109020302,T109020303,T109020304,T109020305,T109020306,T109020307,T109090101,T109090102,T109090201,T109090202,T109090301,T109090302,T109090303,T109090304,T109090305,T109090401}',true),
('R346','Bài toán thực tế: lệch giá trị ở giá trị còn lại','Đúng cấu trúc nhưng giá trị còn lại (thứ hai, hoặc giá trị duy nhất theo hướng khác nếu chỉ có 1) lệch so với đúng','Đúng "90; 60" → nhầm "90; 61"','tinh','{T109010301,T109010302,T109010304,T109010305,T109010306,T109010307,T109010308,T109010309,T109020301,T109020302,T109020303,T109020304,T109020305,T109020306,T109020307,T109090101,T109090102,T109090201,T109090202,T109090301,T109090302,T109090303,T109090304,T109090305,T109090401}',false)
on conflict (ma) do update set ten = excluded.ten, mo_ta = excluded.mo_ta, vi_du = excluded.vi_du,
  nhom = excluded.nhom, ap_dung = excluded.ap_dung, du_phong = excluded.du_phong;
